:setvar DatabaseName TransportationDW

USE [$(DatabaseName)];
GO

SET NOCOUNT ON;
GO

IF OBJECT_ID(N'src.Shipment', N'U') IS NULL
BEGIN
    THROW 50000, 'Run sql/source/01_create_source_schema.sql before seeding source data.', 1;
END;
GO

DELETE FROM src.Delivery_Exception;
DELETE FROM src.Shipment_Status_History;
DELETE FROM src.Shipment;
DELETE FROM src.Route;
DELETE FROM src.Carrier;
DELETE FROM src.Location;
GO

DBCC CHECKIDENT ('src.Location', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('src.Carrier', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('src.Route', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('src.Shipment', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('src.Shipment_Status_History', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('src.Delivery_Exception', RESEED, 0) WITH NO_INFOMSGS;
GO

