    ON v.RouteCode = route.RouteCode
INNER JOIN src.Location AS origin_location
    ON v.OriginLocationCode = origin_location.LocationCode
INNER JOIN src.Location AS destination_location
    ON v.DestinationLocationCode = destination_location.LocationCode
;
