INSERT INTO src.Shipment
(
    ShipmentNumber,
    CarrierID,
    RouteID,
    OriginLocationID,
    DestinationLocationID,
    CustomerReferenceNumber,
    ServiceLevel,
    CurrentStatus,
    ShipmentCreateDateTime,
    PlannedPickupDateTime,
    ActualPickupDateTime,
    PlannedDeliveryDateTime,
    ActualDeliveryDateTime,
    WeightLbs,
    PieceCount,
    ShipmentRevenue,
    ShipmentCost,
    PlannedDistanceMiles,
    ActualDistanceMiles,
    SourceModifiedAt
)
SELECT
    v.ShipmentNumber,
    carrier.CarrierID,
    route.RouteID,
    origin_location.LocationID,
    destination_location.LocationID,
    v.CustomerReferenceNumber,
    v.ServiceLevel,
    v.CurrentStatus,
    CAST(v.ShipmentCreateDateTime AS datetime2(0)),
    CAST(v.PlannedPickupDateTime AS datetime2(0)),
    CAST(v.ActualPickupDateTime AS datetime2(0)),
    CAST(v.PlannedDeliveryDateTime AS datetime2(0)),
