INSERT INTO src.Shipment_Status_History
(
    ShipmentID,
    EventSequenceNumber,
    StatusCode,
    StatusDescription,
    EventDateTime,
    LocationID,
    ScanType,
    EventSource,
    ExceptionCode,
    Notes
)
SELECT
    shipment.ShipmentID,
    v.EventSequenceNumber,
    v.StatusCode,
    v.StatusDescription,
    CAST(v.EventDateTime AS datetime2(0)),
    location.LocationID,
    v.ScanType,
    v.EventSource,
    v.ExceptionCode,
    v.Notes
FROM
