(
    ShipmentNumber,
    ExceptionCode,
    ExceptionDescription,
    ExceptionCategory,
    SeverityCode,
    ExceptionStatus,
    ExceptionDateTime,
    ResolvedDateTime,
    DelayMinutesImpact,
    ResponsibleParty,
    Notes
)
INNER JOIN src.Shipment AS shipment
    ON v.ShipmentNumber = shipment.ShipmentNumber
;
GO

SELECT
    (SELECT COUNT(*) FROM src.Location) AS LocationCount,
    (SELECT COUNT(*) FROM src.Carrier) AS CarrierCount,
    (SELECT COUNT(*) FROM src.Route) AS RouteCount,
    (SELECT COUNT(*) FROM src.Shipment) AS ShipmentCount,
    (SELECT COUNT(*) FROM src.Shipment_Status_History) AS ShipmentStatusHistoryCount,
    (SELECT COUNT(*) FROM src.Delivery_Exception) AS DeliveryExceptionCount;
GO
